// D-37: the approved prototype engine as a class. Everything physical is the prototype's code, verbatim, in
// core.js / terrain.js / gas.js / shaders.js (generated by frontend/scripts/extract-world-engine.py). This file
// only wraps it: it replaces the prototype's DOM controls with methods and its page loop with tick() / draw().
//
// Canvas decision: ONE canvas, ONE GL context, split viewport, exactly as the prototype draws it. With
// setFly(true) the left 60% of the canvas is the fly view and the right 40% is the globe; with fly off the
// globe fills the canvas. `view()` returns the pixel rectangles so a host can overlay or crop them
// (or run two WorldEngine instances on two canvases, each with its own context, if it wants separate panes).
import { createCore, type Core, type CoreGL } from './core.js';
import { WP, FLUIDS } from './presets.js';
import { GlGpuTimer } from './glTimer';
import type {
  EngineOptions,
  EngineOverrides,
  EngineRole,
  FluidKey,
  Readouts,
  SpinMode,
  WorldPreset,
} from './types';

export type { EngineOptions, EngineOverrides, Readouts, WorldPreset } from './types';
export { WP as WORLD_PRESETS, FLUIDS as WORLD_FLUIDS };

export interface FlyState {
  /** Altitude above the ground, km. */
  alt: number;
  /** Longitude and latitude of the camera foot point, radians. */
  lon: number;
  lat: number;
  /** Heading, radians clockwise from north. */
  head: number;
  /** Look pitch, radians (negative looks down). */
  pitch: number;
  /** Prototype's auto-flight toggle (the Fly button). */
  auto: boolean;
}

export interface CpuFields {
  /** Terrain: W x H grid, data = interleaved (elevation km, second channel) per cell; plates, stagnant flag. */
  terrain: { W: number; H: number; data: Float32Array; plates: number; stagnant: boolean } | null;
  /** Climate budget grid (NX x NY): T surface temperature K, rain, u/v wind, land mask, elevation, etc. */
  climate: {
    NX: number;
    NY: number;
    T: Float32Array;
    rain: Float32Array;
    u: Float32Array;
    v: Float32Array;
    land: any;
    elev: any;
    stats: any;
  } | null;
  /** River raster: image + counts. */
  hydro: any;
}

/** Issue #114 (sound spec §3.3): the energy budget's weather arrays, NX x NY cells, row 0 = south pole. */
export interface WeatherFields {
  NX: number;
  NY: number;
  /** EB.h, sea-ice thickness (engine units). */
  iceH: Float32Array;
  /** EB.s, frost and snow on land. */
  snow: Float32Array;
  /** EB.out, 4 per cell: T, smoothed ice, smoothed frost, relative humidity. */
  out: Float32Array;
  /** EB.out2, 4 per cell: rain / rainMax, ocean-current speed, u, v. */
  out2: Float32Array;
  /**
   * The cyclones the clouds draw (EB.cyc, first 12, as cloudStep): centre where the vortex is drawn now (lon drifted
   * by (W.step - born) * drift and wrapped as core.js does), radius r (rad), spin sign s.
   */
  cyclones: { lon: number; lat: number; r: number; s: number }[];
}

/** Issue #114 (§3.3, §8.5): the fly camera basis (body frame) and its drawing constants. */
export interface FlyCameraBasis {
  /**
   * Eye position in planet radii (body frame): up * (1 + (ex * groundKm + alt) / rkm). A world point at height h km over
   * the unit direction d is d * (1 + h * ex / rkm) (the shader's surfR; the cloud shell is 1 + cloudKm * ex / rkm).
   */
  cam: [number, number, number];
  fwd: [number, number, number];
  rt: [number, number, number];
  up: [number, number, number];
  /** Planet radius, km. */
  rkm: number;
  /** Vertical exaggeration of the drawn relief (3 rocky, 2 gas). */
  ex: number;
  /**
   * tan of the half vertical field of view (FLY_FS: rd = fwd + q.x * fov * rt + q.y * fov * up, q.y in [-1, 1]); 0.62 is
   * a 63.6 degree vertical view. The horizontal extent is fov * aspect, aspect = the fly pane's width / height.
   */
  fov: number;
}

/** The fly view's field of view: core.js draw sets `gl.uniform1f(uF.uFov, 0.62)`. */
export const FLY_FOV = 0.62;

/** Issue #114 (blue 13, for #117): where a body-frame point (planet radii) falls in the fly view. */
export interface FlyProjection {
  /** -1 (left edge) .. 1 (right edge) of the fly pane; outside that range the point is off screen. */
  x: number;
  /** -1 (bottom) .. 1 (top). */
  y: number;
  /** The point is in front of the eye. */
  inFront: boolean;
}

/**
 * Project a body-frame point (planet radii, see FlyCameraBasis.cam) into the fly view, inverting FLY_FS's ray
 * rd = fwd + q.x * fov * rt + q.y * fov * up with q = (2 frag - res) / res.y. `aspect` is the fly pane's width / height
 * (core draws the fly view into viewport (0, 0, round(0.6 w), h); not the canvas aspect). Visible: inFront and |x|, |y| <= 1.
 */
export function projectFly(
  b: Pick<FlyCameraBasis, 'cam' | 'fwd' | 'rt' | 'up' | 'fov'>,
  aspect: number,
  p: readonly [number, number, number],
): FlyProjection {
  const v = [p[0] - b.cam[0], p[1] - b.cam[1], p[2] - b.cam[2]];
  const dot = (a: readonly number[]) => v[0]! * a[0]! + v[1]! * a[1]! + v[2]! * a[2]!;
  const a = dot(b.fwd);
  if (!(a > 0)) return { x: NaN, y: NaN, inFront: false };
  return { x: dot(b.rt) / (a * b.fov * aspect), y: dot(b.up) / (a * b.fov), inFront: true };
}

export interface EngineState {
  Tstar: number;
  orbit: number;
  Ps: number;
  obl: number;
  ecc: number;
  co2: boolean;
  clouds: boolean;
  zoom: number;
  yaw: number;
  pitch: number;
  fluid: FluidKey;
  spin: SpinMode;
  tect: 'auto' | 'plates' | 'lid';
  overlay: number;
  timeSec: number;
  gas: boolean;
  locked: boolean;
  rotation: number;
}

/** How often a disposed engine checks whether its shaders have finished compiling (UI pacing, ms). */
export const DISPOSE_POLL_MS = 100;
/**
 * Longest a disposed engine waits for a compile still running (ms). After it the engine stops polling and drops the
 * context to the browser without `loseContext()` (which would block on that compile); it goes with the canvas.
 */
export const DISPOSE_MAX_WAIT_MS = 180_000;

export class WorldEngine {
  private core: Core;
  private canvas: HTMLCanvasElement;
  private tickN = 0;
  private isReady = false;
  private readyP: Promise<void> | null = null;
  private disposed = false;
  private readonly role: EngineRole;
  /** Roadmap 0.1, dev only: GPU time of each tick (null when off or unsupported). */
  private readonly gpuTimer: GlGpuTimer | null;
  /** Live fly-camera state. Assigning a field takes effect at the next draw(). */
  readonly fly: FlyState;

  constructor(canvas: HTMLCanvasElement, opts: EngineOptions = {}) {
    this.canvas = canvas;
    // The prototype creates its context with fixed attributes; a context made first keeps its own, so ask for a
    // readable buffer here when a host needs to capture the frame (parity mode).
    if (opts.preserveDrawingBuffer)
      canvas.getContext('webgl2', {
        preserveDrawingBuffer: true,
        antialias: false,
        alpha: false,
        powerPreference: 'high-performance',
      });
    // Issue #93: the shaders are submitted here and compile in the background (see whenReady).
    this.role = opts.role ?? 'both';
    this.core = createCore(canvas, { role: this.role });
    // The same context the core made (getContext returns it again); read-only timing around tick().
    this.gpuTimer = opts.gpuTiming ? GlGpuTimer.create(canvas.getContext('webgl2')) : null;
    const W = this.core.W;
    this.fly = {
      get alt() {
        return W.flyAlt;
      },
      set alt(v: number) {
        W.flyAlt = v;
      },
      get lon() {
        return W.flyLon;
      },
      set lon(v: number) {
        W.flyLon = v;
      },
      get lat() {
        return W.flyLat;
      },
      set lat(v: number) {
        W.flyLat = v;
      },
      get head() {
        return W.flyHead;
      },
      set head(v: number) {
        W.flyHead = v;
      },
      get pitch() {
        return W.flyPitch;
      },
      set pitch(v: number) {
        W.flyPitch = v;
      },
      get auto() {
        return W.flyAuto;
      },
      set auto(v: boolean) {
        W.flyAuto = v;
      },
    };
  }

  /**
   * True once the shaders are compiled and linked. Never waits for the driver (KHR_parallel_shader_compile; without
   * the extension it links at once, which waits as the prototype did). Throws the compile or link log.
   */
  pollReady(): boolean {
    if (!this.isReady) this.isReady = (this.core.W.gl as CoreGL).poll();
    return this.isReady;
  }

  /**
   * Resolves when the shaders are linked, checking every 16 ms so the page keeps running meanwhile (issue #93: the fly
   * shader took about 60 s on a cold ANGLE D3D11 cache). Rejects with the compile or link log. A host that loads a
   * world before this resolves still works: the first step or draw links the programs, waiting for the driver.
   */
  whenReady(): Promise<void> {
    if (!this.readyP)
      this.readyP = new Promise<void>((resolve, reject) => {
        const check = () => {
          if (this.disposed)
            return reject(new Error('world engine disposed before its shaders were ready'));
          try {
            if (this.pollReady()) resolve();
            else setTimeout(check, 16);
          } catch (err) {
            reject(err instanceof Error ? err : new Error(String(err)));
          }
        };
        check();
      });
    return this.readyP;
  }

  /** Programs this instance has submitted: 3 for a 'globe' (no fly shader) or 'fly' engine (no globe shader), 4 for 'both'. */
  programCount(): number {
    return (this.core.W.gl as CoreGL).programs();
  }

  /** Load a world: a preset object, or the id of one of the prototype's example presets. Rebuilds terrain and spin-up. */
  setPreset(p: WorldPreset | string): void {
    const pr = typeof p === 'string' ? WP.find((q) => q.id === p) : p;
    if (!pr) throw new Error('unknown preset ' + String(p));
    if (pr.ob) this.core.ORB[pr.id] = pr.ob;
    if (pr.oceanF != null) this.core.OCEANF[pr.id] = pr.oceanF;
    this.core.setPreset(pr);
  }

  /**
   * The prototype's slider and pill handlers, by name. Atmosphere and orbit sliders only refresh the model
   * (as in the prototype); fluid, spin and tect rebuild the world; overlay, clouds, zoom, yaw, pitch only redraw.
   */
  setOverrides(o: EngineOverrides): void {
    const c = this.core,
      W = c.W;
    let model = false,
      reset = false;
    if (o.Tstar != null) {
      W.Tstar = o.Tstar;
      model = true;
    }
    if (o.orbit != null) {
      W.orbit = o.orbit;
      model = true;
    }
    if (o.Ps != null) {
      W.Ps = o.Ps;
      model = true;
    }
    if (o.obl != null) {
      W.obl = o.obl;
      model = true;
    }
    if (o.ecc != null) {
      W.ecc = o.ecc;
      model = true;
    }
    if (o.co2 != null) {
      W.co2Therm = o.co2;
      model = true;
    }
    if (o.season != null) W.season = o.season;
    if (o.overlay != null) W.overlay = o.overlay;
    if (o.clouds != null) W.clouds = o.clouds;
    if (o.zoom != null) W.zoom = o.zoom;
    if (o.yaw != null) W.yaw = o.yaw;
    if (o.pitch != null) W.pitch = o.pitch;
    if (o.timeSec != null) {
      W.timeSec = o.timeSec;
      model = true;
    }
    if (o.fluid != null) {
      W.fluid = o.fluid;
      reset = true;
    }
    if (o.spin != null) {
      W.spinMode = o.spin;
      W.p = c.applySpin(W.base);
      reset = true;
    }
    if (o.tect != null) {
      W.tect = o.tect;
      reset = true;
    }
    if (reset) c.resetWorld();
    else if (model) {
      W.m = c.worldModel();
      c.worldUi();
    }
  }

  /** Switch the split fly view on or off (the prototype's Fly button). Aims the camera on entry. */
  setFly(on: boolean): void {
    // Issue #93 B10: a globe-role engine has no fly program; flying would make the core link FLY_FS synchronously
    // (a 35 s block on a cold ANGLE cache). Flying belongs to a 'fly' or 'both' engine, so the call is ignored.
    if (on && this.role === 'globe') {
      if (import.meta.env.DEV)
        console.warn('WorldEngine.setFly(true) ignored on a globe-role engine');
      return;
    }
    const c = this.core,
      W = c.W;
    W.fly = on;
    if (on) {
      W.flyAlt = W.m && W.m.gas ? 6000 : 400;
      if (!c.flyAimPeak()) c.flyAimDefault();
    }
  }
  get flying(): boolean {
    return !!this.core.W.fly;
  }

  /** Fly camera setters for hosts (the same fields as `fly`). */
  setFlyAlt(km: number): void {
    this.core.W.flyAlt = km;
  }
  /** Put the fly camera's foot point at a place (the prototype's globe click). */
  setFlyPlace(lon: number, lat: number): void {
    this.core.W.flyLon = lon;
    this.core.W.flyLat = lat;
  }
  setFlyAuto(on: boolean): void {
    this.core.W.flyAuto = on;
  }

  /** Move the fly camera: dKm forward, side km to the right. */
  flyMove(dKm: number, side = 0): void {
    this.core.flyMove(dKm, side);
  }
  /** Allowed fly altitude range in km for the current world. */
  altRange(): [number, number] {
    return this.core.altRange();
  }
  flyAimPeak(): boolean {
    return this.core.flyAimPeak();
  }
  flyAimDefault(): void {
    this.core.flyAimDefault();
  }

  /** Canvas pixel (x, y, in drawing-buffer pixels, y down) to {lon, lat} on the globe, or null. */
  globePick(x: number, y: number): { lon: number; lat: number } | null {
    return this.core.globePick(x, y);
  }

  /** Pixel rectangles of the last draw: { gx: fly width, gw: globe width, w, h } and the globe's camera. */
  view(): {
    gx: number;
    gw: number;
    w: number;
    h: number;
    tilt: number;
    spin: number;
    frame: number;
  } | null {
    return this.core.W.view ?? null;
  }

  get playing(): boolean {
    return this.core.W.playing;
  }
  set playing(v: boolean) {
    this.core.W.playing = v;
  }
  /** Spin-up steps left (0 once the world has settled). */
  get spinup(): number {
    return this.core.W.spinup;
  }

  /**
   * One page-loop frame of the prototype (dt seconds, capped like the prototype at 0.06): auto-flight, the
   * simulation tick, the spin advance, the redraw and the readout refresh every 20 ticks. No world is drawn while it
   * spins up: the prototype skipped only gas giants, but the app covers every world with the opaque "Forming" overlay
   * then, so the frames were never seen (issue #93). The host calls this from requestAnimationFrame while the canvas is visible.
   */
  tick(dt: number): void {
    const timer = this.gpuTimer;
    if (!timer) return this.tickNow(dt);
    timer.begin();
    try {
      this.tickNow(dt);
    } finally {
      timer.end();
    }
  }

  /**
   * GPU milliseconds per tick (roadmap 0.1, dev only), median and 95th percentile of the last 240,
   * or null without timing (option off, no EXT_disjoint_timer_query_webgl2, or no sample yet).
   */
  gpuMs(): { p50: number; p95: number; samples: number } | null {
    const s = this.gpuTimer?.stats;
    const p50 = s?.percentile(0.5);
    const p95 = s?.percentile(0.95);
    if (!s || p50 == null || p95 == null) return null;
    return { p50, p95, samples: s.count };
  }

  private tickNow(dt: number): void {
    const c = this.core,
      W = c.W;
    dt = Math.min(0.06, dt || 0);
    const need = W.spinup > 0;
    if (W.fly && W.flyAuto) {
      c.flyMove(Math.max(W.flyAlt * 0.4, 4) * dt, 0);
      if (!W.playing) W.gl.draw(W.m);
    }
    if (W.playing || need) {
      W.gl.tick(W.m, W.playing, dt);
      if (W.playing)
        W.spin += W.m.gas ? (W.timeSec < 1000 ? dt * W.timeSec * W.m.Om : 0) : dt * 0.09;
      if (W.spinup === 0) W.gl.draw(W.m);
      if (this.tickN++ % 20 === 0) c.worldUi();
    }
  }

  /**
   * Finish the spin-up as the artifact's test page does: W.gl.tick until done, no redraw in between.
   * The prototype gives each tick a 14 ms wall-clock budget, so how many cloud steps a spin-up takes depends on machine
   * speed. With `virtualClock` performance.now() advances 1 ms per call during the spin-up, which makes the step count
   * identical on every machine (used by the parity hook; the artifact's driver must do the same to be comparable).
   */
  spinUp(dt = 1 / 60, virtualClock = false): void {
    const W = this.core.W;
    const real = performance.now.bind(performance);
    let t = 0;
    if (virtualClock) performance.now = () => (t += 1);
    try {
      for (let g = 0; W.spinup > 0 && g < 100000; g++) W.gl.tick(W.m, false, dt);
    } finally {
      performance.now = real;
    }
  }

  /** Run page-loop ticks (with redraws) until the spin-up is done. */
  settle(maxTicks = 100000): void {
    const W = this.core.W;
    for (let i = 0; i < maxTicks && W.spinup > 0; i++) this.tick(0.016);
  }

  /** Draw the current state now. */
  draw(): void {
    const W = this.core.W;
    if (W.gl && W.m) W.gl.draw(W.m);
  }

  /** Everything the prototype's side panel showed: rows, caption, title tag, model, spin-up state. */
  readouts(): Readouts {
    const W = this.core.W;
    this.core.worldUi();
    return {
      rows: W.rows,
      caption: W.cap,
      tag: W.tag,
      provenance: 'model_dependent',
      building: !!(W.m.gas && W.spinup > 0),
      spinup: W.spinup,
      step: W.step,
      model: W.m,
      stats: this.core.EB.stats,
    };
  }

  /** The prototype's one-paragraph caption for the current world. */
  notes(): string {
    this.core.worldUi();
    return this.core.W.cap;
  }

  /** CPU-side arrays for haptics and queries (references, not copies; do not write to them). */
  cpuFields(): CpuFields {
    const W = this.core.W,
      EB = this.core.EB;
    return {
      terrain: W.terr
        ? {
            W: W.terr.W,
            H: W.terr.H,
            data: W.terr.data,
            plates: W.terr.plates,
            stagnant: !!W.terr.stagnant,
          }
        : null,
      climate: EB.ready
        ? {
            NX: EB.NX,
            NY: EB.NY,
            T: EB.T,
            rain: EB.rain,
            u: EB.u,
            v: EB.v,
            land: EB.land,
            elev: EB.elev,
            stats: EB.stats,
          }
        : null,
      hydro: W.hydro ?? null,
    };
  }

  /**
   * Issue #114 (sound spec §3.3): the energy budget's weather arrays (references; do not write). Null until the budget is
   * ready, and null on a gas giant: EB keeps the previous rocky world's state across a switch to a giant.
   */
  weatherFields(): WeatherFields | null {
    const EB = this.core.EB;
    if (!EB.ready || this.core.W.m?.gas) return null;
    // core.js cloudStep draws the first 12 entries at lon + (W.step - born) * drift, wrapped with its 6.2832.
    const step = this.core.W.step as number;
    const cyc = (
      (EB.cyc ?? []) as {
        lon: number;
        lat: number;
        r: number;
        s: number;
        born?: number;
        drift?: number;
      }[]
    )
      .slice(0, 12)
      .map((c) => {
        const lon = c.lon + (step - (c.born ?? step)) * (c.drift ?? 0);
        return {
          lon: ((((lon + Math.PI) % 6.2832) + 6.2832) % 6.2832) - Math.PI,
          lat: c.lat,
          r: c.r,
          s: c.s,
        };
      });
    return {
      NX: EB.NX,
      NY: EB.NY,
      iceH: EB.h,
      snow: EB.s,
      out: EB.out,
      out2: EB.out2,
      cyclones: cyc,
    };
  }

  /**
   * Issue #114 (§3.3): the gas simulation's field, 256 x 128 x [u, v, vorticity, storm stamp], row 0 = south pole,
   * column 0 = lon -pi. `exportField(false)` rewrites the simulation's own buffer from the current state, so the array
   * is live: the next call (or the next GPU upload) overwrites it. Null on rocky worlds (the simulation outlives a switch
   * to a rocky world, so its field would be stale).
   */
  gasField(): Float32Array | null {
    if (!this.core.W.m?.gas) return null;
    const gs = this.core.getGS();
    return gs ? (gs.exportField(false) as Float32Array) : null;
  }

  /** Issue #114 (§3.3): the raw terrain cell under (lon, lat) in km, clamped at sea level on ocean worlds (core.groundKm). */
  groundKm(lon: number, lat: number): number {
    return this.core.groundKm(lon, lat);
  }

  /**
   * Issue #114 (§3.3, §8.5): the fly camera's basis, from core.flyCamera(m, 0, 0, [0, 0, 1]). Tilt, spin and the light
   * vector change only the light direction, never the basis. Null before a world is loaded.
   */
  flyCameraBasis(): FlyCameraBasis | null {
    const W = this.core.W;
    if (!W.m || !W.p) return null;
    const c = this.core.flyCamera(W.m, 0, 0, [0, 0, 1]);
    const v3 = (v: number[]): [number, number, number] => [v[0]!, v[1]!, v[2]!];
    return {
      cam: v3(c.uCam),
      fwd: v3(c.uFwd),
      rt: v3(c.uRt),
      up: v3(c.uUp),
      rkm: c.rkm,
      ex: c.ex,
      fov: FLY_FOV,
    };
  }

  /**
   * The prototype's current slider and pill values (what its controls would show), read from its own state.
   * Hosts use this to draw controls; the engine stays the single source of truth.
   */
  state(): EngineState {
    const W = this.core.W;
    return {
      Tstar: W.Tstar,
      orbit: W.orbit,
      Ps: W.Ps,
      obl: W.obl,
      ecc: W.ecc,
      co2: !!W.co2Therm,
      clouds: !!W.clouds,
      zoom: W.zoom,
      yaw: W.yaw,
      pitch: W.pitch,
      fluid: W.fluid,
      spin: W.spinMode,
      tect: W.tect,
      overlay: W.overlay,
      timeSec: W.timeSec,
      gas: !!(W.m && W.m.gas),
      locked: !!(W.p && W.p.locked),
      rotation: W.spin,
    };
  }

  /** Copy the planet's turn angle from another instance (two canvases of one world stay in the same phase). */
  syncSpin(other: WorldEngine): void {
    this.core.W.spin = other.core.W.spin;
  }

  /**
   * Release the GL context. Issue #93 regression fix: `loseContext()` waits for every shader compile still running in
   * the driver, so releasing an engine whose fly shader was still compiling froze the page for about 35 s on a cold
   * ANGLE D3D11 cache (React's development double mount did this on every first open; closing the build early did it
   * in production). While programs are still compiling the context is released once the driver reports them done
   * (polled every DISPOSE_POLL_MS, never blocking). If the compile is still running after DISPOSE_MAX_WAIT_MS the
   * engine gives up without calling `loseContext()` (issue #93 B1: calling it then would still block on that compile):
   * polling stops (no timer keeps the engine alive), and once its host drops the engine the browser reclaims the
   * context with the detached canvas.
   */
  dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    try {
      this.gpuTimer?.dispose();
    } catch {
      /* the context is already gone */
    }
    const lose = () => {
      const gl = this.canvas.getContext('webgl2');
      gl?.getExtension('WEBGL_lose_context')?.loseContext();
    };
    const t0 = Date.now();
    const settled = (): boolean => {
      if (this.isReady) return true;
      try {
        return (this.core.W.gl as CoreGL).poll();
      } catch {
        return true; // a compile or link error: nothing is running any more
      }
    };
    const tryLose = () => {
      if (settled()) lose();
      else if (Date.now() - t0 < DISPOSE_MAX_WAIT_MS) setTimeout(tryLose, DISPOSE_POLL_MS);
      else if (import.meta.env.DEV)
        console.warn(
          'world engine: shaders still compiling after dispose; context left to the browser',
        );
    };
    tryLose();
  }
}
